def room_numbers(meetings, clean):
    order = sorted(range(len(meetings)), key=lambda i: (meetings[i][0], i))
    ready = []
    rooms = [0] * len(meetings)
    for i in order:
        start, end = meetings[i]
        room = None
        for r in range(len(ready) - 1, -1, -1):
            if ready[r] <= start:
                room = r
        if room is None:
            room = len(ready)
            ready.append(0)
        ready[room] = end + clean
        rooms[i] = room
    return rooms
